/**
 * Bridge to the cuspis-panel wasm (native/cuspis-panel): batch panel / shock-expansion forces.
 *
 * The wasm is embedded as base64 (panel-wasm.ts, regenerated by `npm run build:wasm`) and instantiated
 * synchronously, the same way sym-euler.ts loads euler-wasm.ts, so it works in the browser main thread,
 * in a Web Worker and in Node without a fetch. One kernel per JS realm (one per worker).
 *
 * Mesh geometry is fed from panel.ts `panelGeom` (area, unit normal, centroid, reclassified surface id,
 * wetted area), so the wasm integrates exactly the triangles the TS loop integrates. The raw mesh is
 * passed as well for the shock-expansion strip/face merge, which the kernel rebuilds itself
 * (shockexp.ts keeps its face cache private).
 */
import { PANEL_WASM_B64 } from "./panel-wasm";
import { panelGeom } from "./panel";
import type { AeroMethod, TriMesh } from "./types";

/** f64 per input point: mach, alphaDeg, betaDeg, hasRates, p, q, r, V, qDyn, Cf, wRare, pVisc */
export const STRIDE_IN = 12;
/** f64 per output point: cl, cd, cy, cm, cn, cll, ca, ld, cnA, cdFric, cdBase, xCp */
export const STRIDE_OUT = 12;

export const KERNEL_METHOD: Partial<Record<AeroMethod, number>> = { newtonian: 0, tangent: 1, mixed: 2, cbaero: 3 };

export function kernelSupports(method: AeroMethod): boolean {
  return KERNEL_METHOD[method] !== undefined;
}

export interface KernelConfig {
  method: AeroMethod;
  gamma: number;
  useCone: boolean;
  cgX: number;
  sRef: number;
  lRef: number;
}

interface Exports {
  memory: WebAssembly.Memory;
  cp_version: () => number;
  cp_stride_in: () => number;
  cp_stride_out: () => number;
  cp_alloc: (n: number) => number;
  cp_free: (ptr: number, n: number) => void;
  cp_mesh_load: (nt: number, geom: number, surf: number, aWet: number, nv: number, pos: number, ind: number, surfaces: number, tags: number) => number;
  cp_mesh_drop: (h: number) => void;
  cp_mesh_count: () => number;
  cp_eval: (h: number, method: number, gamma: number, useCone: number, cgX: number, sRef: number, lRef: number, n: number, inp: number, out: number) => number;
  cp_clear_caches: () => void;
}

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export const PANEL_WASM_BYTES = Math.floor((PANEL_WASM_B64.length * 3) / 4);

export class PanelKernel {
  private handles = new WeakMap<TriMesh, { h: number; pos: unknown; ind: unknown; surf: unknown; tags: unknown }>();
  private scratch = { ptr: 0, bytes: 0 };

  private constructor(private x: Exports) {
    if (x.cp_stride_in() !== STRIDE_IN || x.cp_stride_out() !== STRIDE_OUT) throw new Error("cuspis-panel wasm stride mismatch: rebuild with npm run build:wasm");
  }

  /** Synchronous instantiate from the embedded module. Throws if WebAssembly is unavailable. */
  static create(): PanelKernel {
    const mod = new WebAssembly.Module(decode(PANEL_WASM_B64) as BufferSource);
    return new PanelKernel(new WebAssembly.Instance(mod, {}).exports as unknown as Exports);
  }

  static async createAsync(): Promise<PanelKernel> {
    const { instance } = await WebAssembly.instantiate(decode(PANEL_WASM_B64) as BufferSource, {});
    return new PanelKernel(instance.exports as unknown as Exports);
  }

  version(): number {
    return this.x.cp_version();
  }

  meshCount(): number {
    return this.x.cp_mesh_count();
  }

  private alloc(bytes: number): number {
    const p = this.x.cp_alloc(bytes);
    if (!p) throw new Error("cuspis-panel: out of memory");
    return p;
  }

  private put(arr: ArrayBufferView & { length: number; BYTES_PER_ELEMENT: number }, Ctor: { new (b: ArrayBuffer, o: number, n: number): { set(a: ArrayLike<number>): void } }): { ptr: number; bytes: number } {
    const bytes = Math.max(8, arr.length * arr.BYTES_PER_ELEMENT);
    const ptr = this.alloc(bytes);
    // view after alloc: growing memory detaches older views
    new Ctor(this.x.memory.buffer, ptr, arr.length).set(arr as unknown as ArrayLike<number>);
    return { ptr, bytes };
  }

  /** Load (or reuse) a mesh. Same identity rule as panelGeom: positions/indices/surfaces arrays must be unchanged. */
  load(mesh: TriMesh): number {
    const hit = this.handles.get(mesh);
    if (hit && hit.pos === mesh.positions && hit.ind === mesh.indices && hit.surf === mesh.surfaces && hit.tags === mesh.tags) return hit.h;
    if (hit) this.x.cp_mesh_drop(hit.h);
    const g = panelGeom(mesh);
    const nt = g.area.length;
    const geom = new Float64Array(nt * 7);
    geom.set(g.area, 0);
    geom.set(g.nx, nt);
    geom.set(g.ny, 2 * nt);
    geom.set(g.nz, 3 * nt);
    geom.set(g.cx, 4 * nt);
    geom.set(g.cy, 5 * nt);
    geom.set(g.cz, 6 * nt);
    const bufs = [
      this.put(geom, Float64Array),
      this.put(g.surf, Uint16Array),
      this.put(mesh.positions, Float64Array),
      this.put(mesh.indices, Uint32Array),
      this.put(mesh.surfaces, Uint8Array),
    ];
    const tags = mesh.tags && mesh.tags.length >= nt ? this.put(mesh.tags, Int32Array) : null;
    const h = this.x.cp_mesh_load(nt, bufs[0].ptr, bufs[1].ptr, g.aWet, mesh.positions.length / 3, bufs[2].ptr, bufs[3].ptr, bufs[4].ptr, tags ? tags.ptr : 0);
    for (const b of bufs) this.x.cp_free(b.ptr, b.bytes);
    if (tags) this.x.cp_free(tags.ptr, tags.bytes);
    if (!h) throw new Error("cuspis-panel: mesh load failed");
    this.handles.set(mesh, { h, pos: mesh.positions, ind: mesh.indices, surf: mesh.surfaces, tags: mesh.tags });
    return h;
  }

  drop(mesh: TriMesh) {
    const hit = this.handles.get(mesh);
    if (!hit) return;
    this.x.cp_mesh_drop(hit.h);
    this.handles.delete(mesh);
  }

  /** `input` is n·STRIDE_IN (see STRIDE_IN). Returns n·STRIDE_OUT. */
  eval(mesh: TriMesh, cfg: KernelConfig, input: Float64Array, out?: Float64Array): Float64Array {
    const code = KERNEL_METHOD[cfg.method];
    if (code === undefined) throw new Error(`cuspis-panel: method ${cfg.method} is not in the kernel`);
    const h = this.load(mesh);
    const n = Math.floor(input.length / STRIDE_IN);
    const res = out ?? new Float64Array(n * STRIDE_OUT);
    const need = n * (STRIDE_IN + STRIDE_OUT) * 8;
    if (this.scratch.bytes < need) {
      if (this.scratch.ptr) this.x.cp_free(this.scratch.ptr, this.scratch.bytes);
      const bytes = Math.max(need, 4096);
      this.scratch = { ptr: this.alloc(bytes), bytes };
    }
    const inPtr = this.scratch.ptr;
    const outPtr = inPtr + n * STRIDE_IN * 8;
    new Float64Array(this.x.memory.buffer, inPtr, n * STRIDE_IN).set(input.subarray(0, n * STRIDE_IN));
    const rc = this.x.cp_eval(h, code, cfg.gamma, cfg.useCone ? 1 : 0, cfg.cgX, cfg.sRef, cfg.lRef, n, inPtr, outPtr);
    if (rc !== 0) throw new Error(`cuspis-panel: eval failed (${rc})`);
    res.set(new Float64Array(this.x.memory.buffer, outPtr, n * STRIDE_OUT));
    return res;
  }

  clearCaches() {
    this.x.cp_clear_caches();
  }
}

let shared: PanelKernel | null | undefined;

/** Process-wide kernel, or null when WebAssembly cannot instantiate it here. */
export function panelKernel(): PanelKernel | null {
  if (shared !== undefined) return shared;
  try {
    shared = typeof WebAssembly === "object" ? PanelKernel.create() : null;
  } catch {
    shared = null;
  }
  return shared;
}
